mapper.select:
SELECT c.id AS chunk_id, c.doc_id AS doc_id, c.kb_id AS kb_id, c.text AS text, c.ordinal AS ordinal, c.chunk_type AS chunk_type, c.parent_chunk_id AS parent_chunk_id, c.page_start AS page_start, c.page_end AS page_end, c.block_ids_json AS block_ids_json, c.context_prefix AS context_prefix, COALESCE(d.title, '') AS title, (c.embedding_vec <=> CAST(#{vectorLiteral} AS vector)) AS distance FROM kb_chunk c JOIN kb_base b ON b.id = c.kb_id AND b.deleted = FALSE LEFT JOIN kb_document d ON d.id = c.doc_id AND d.deleted = FALSE WHERE c.deleted = FALSE AND c.embedding_vec IS NOT NULL AND c.workspace_id = #{workspaceId} AND c.doc_version = d.active_version
AND c.kb_id IN
#{kid}
AND (
${vfSql} TRUE
)
AND (btrim(coalesce(d.acl_principals, '')) IN ('', '[]')
OR d.acl_principals LIKE CONCAT('%', #{acl}, '%')
)
ORDER BY c.embedding_vec <=> CAST(#{vectorLiteral} AS vector) LIMIT #{k}

SELECT c.id AS chunk_id, c.doc_id AS doc_id, c.kb_id AS kb_id, c.text AS text, c.ordinal AS ordinal, c.chunk_type AS chunk_type, c.parent_chunk_id AS parent_chunk_id, c.page_start AS page_start, c.page_end AS page_end, c.block_ids_json AS block_ids_json, c.context_prefix AS context_prefix, COALESCE(d.title, '') AS title, 0.0 AS distance,
(CASE WHEN strpos(lower(coalesce(c.context_prefix, '') || ' ' || coalesce(c.text, '')), #{t}) > 0 THEN 1 ELSE 0 END)
+ 0
0
AS keyword_hits FROM kb_chunk c JOIN kb_base b ON b.id = c.kb_id AND b.deleted = FALSE LEFT JOIN kb_document d ON d.id = c.doc_id AND d.deleted = FALSE WHERE c.deleted = FALSE AND c.workspace_id = #{workspaceId}
AND coalesce(c.chunk_type, 'CHILD') != 'PARENT' AND c.doc_version = d.active_version
AND c.kb_id IN
#{kid}
AND (
${vfSql} TRUE
)
AND (btrim(coalesce(d.acl_principals, '')) IN ('', '[]')
OR d.acl_principals LIKE CONCAT('%', #{acl}, '%')
)
AND (
strpos(lower(coalesce(c.context_prefix, '') || ' ' || coalesce(c.text, '')), #{t}) > 0
)
AND 1 = 0
ORDER BY keyword_hits DESC, c.ordinal LIMIT #{k}
